// Independent exhaustive enumeration of polygroups of order n (n <= 5) -- Peirce-orbit method.
// Different from the search in polygroups_n5.cpp: no backtracking over cells, no pruning rules.
//
// A polygroup structure is the ternary relation  T = {(x,y,z) : z in x o y}.  Axiom (iii) (reversibility) says
//   (x,y,z) in T  <=>  (z, y^-1, x) in T  <=>  (x^-1, z, y) in T ,
// so T is a union of orbits of the group generated by these two maps ("Peirce orbits").
// The identity axioms force all triples containing e.  The remaining (free) triples have all entries != e.
// We enumerate ALL unions of free orbits (2^k, k small) for one representative inverse involution per
// cycle type, and keep those that satisfy associativity and have non-empty hyperproducts.
#include <bits/stdc++.h>
using namespace std;
int n;
int main(int argc,char**argv){
    n=atoi(argv[1]);
    int m=n-1;                       // non-identity elements 1..m
    long long total_labeled=0;
    for(int t=0;2*t<=m;++t){         // t transpositions, m-2t fixed points
        vector<int> inv(n); iota(inv.begin(),inv.end(),0);
        for(int i=0;i<t;++i){ inv[1+2*i]=2+2*i; inv[2+2*i]=1+2*i; }
        // orbits of free triples
        auto id=[&](int x,int y,int z){return (x*n+y)*n+z;};
        vector<int> orb(n*n*n,-1); vector<vector<array<int,3>>> orbits;
        for(int x=1;x<n;++x)for(int y=1;y<n;++y)for(int z=1;z<n;++z){
            if(orb[id(x,y,z)]!=-1) continue;
            int k=orbits.size(); orbits.push_back({});
            vector<array<int,3>> st={{x,y,z}}; orb[id(x,y,z)]=k;
            while(!st.empty()){
                auto a=st.back(); st.pop_back(); orbits[k].push_back(a);
                array<int,3> b1={a[2],inv[a[1]],a[0]}, b2={inv[a[0]],a[2],a[1]};
                for(auto b:{b1,b2}) if(orb[id(b[0],b[1],b[2])]==-1){orb[id(b[0],b[1],b[2])]=k; st.push_back(b);}
            }
        }
        int K=orbits.size();
        // forced part of the table
        vector<vector<unsigned>> base(n,vector<unsigned>(n,0));
        for(int x=0;x<n;++x){ base[0][x]|=1u<<x; base[x][0]|=1u<<x; }
        for(int x=1;x<n;++x) base[x][inv[x]]|=1u;     // e in x o x^-1
        // per-orbit contribution to table cells
        vector<vector<unsigned>> contrib(K,vector<unsigned>(n*n,0));
        for(int k=0;k<K;++k) for(auto&a:orbits[k]) contrib[k][a[0]*n+a[1]]|=1u<<a[2];
        long long cnt=0;
        vector<unsigned> cell(n*n);
        for(unsigned long long mask=0;mask<(1ULL<<K);++mask){
            for(int x=0;x<n;++x)for(int y=0;y<n;++y)cell[x*n+y]=base[x][y];
            for(int k=0;k<K;++k) if(mask>>k&1) for(int c=0;c<n*n;++c) cell[c]|=contrib[k][c];
            bool ok=true;
            for(int x=1;x<n&&ok;++x)for(int y=1;y<n;++y) if(cell[x*n+y]==0){ok=false;break;}
            if(!ok) continue;
            for(int i=0;i<n&&ok;++i)for(int j=0;j<n&&ok;++j)for(int l=0;l<n;++l){
                unsigned lhs=0,rhs=0;
                for(int s=0;s<n;++s) if(cell[i*n+j]>>s&1) lhs|=cell[s*n+l];
                for(int u=0;u<n;++u) if(cell[j*n+l]>>u&1) rhs|=cell[i*n+u];
                if(lhs!=rhs){ok=false;break;}
            }
            if(!ok) continue;
            ++cnt;
            printf("T %d",t);
            for(int x=0;x<n;++x)for(int y=0;y<n;++y)printf(" %u",cell[x*n+y]);
            printf("\n");
        }
        fprintf(stderr,"n=%d inverse type with %d transposition(s): %d free orbits, %lld labelled solutions\n",n,t,K,cnt);
        total_labeled+=cnt;
    }
    return 0;
}
